import bpy, os, json
from mathutils import Vector
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
tower=bpy.data.objects.get('V4 | torre documental'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador'); floor=bpy.data.objects.get('V4 | estacao laje 0')
if not tower or not hall or not floor: raise RuntimeError('V4 ausente')
T=tower.matrix_world.translation.xy.copy(); H=hall.matrix_world.translation.xy.copy(); EX=(H-T).normalized(); EY=Vector((-EX.y,EX.x))
def points(o):
 if o.type=='MESH' and len(o.data.vertices): return [o.matrix_world@v.co for v in o.data.vertices]
 if o.type=='CURVE':
  out=[]
  for sp in o.data.splines:
   if sp.type=='BEZIER': out += [o.matrix_world@bp.co for bp in sp.bezier_points]
   else: out += [o.matrix_world@Vector((p.co.x,p.co.y,p.co.z)) for p in sp.points]
  if out:return out
 return [o.matrix_world@Vector(c) for c in o.bound_box]
def row(o):
 ps=points(o);xs=[p.x for p in ps];ys=[p.y for p in ps];zs=[p.z for p in ps];s=[];l=[]
 for p in ps:
  r=p.xy-T;s.append(float(r.dot(EX)));l.append(float(r.dot(EY)))
 return {'name':o.name,'type':o.type,'collections':[c.name for c in o.users_collection],'center_xy':[round((min(xs)+max(xs))/2,3),round((min(ys)+max(ys))/2,3)],'s_range':[round(min(s),3),round(max(s),3)],'l_range':[round(min(l),3),round(max(l),3)],'z_range':[round(min(zs),3),round(max(zs),3)],'props':{k:o[k] for k in o.keys()}}
# exact historical anchors and all objects whose metadata/name identifies Elevador Lacerda
candidates=[]
for o in bpy.data.objects:
 text=(o.name+' '+str({k:o[k] for k in o.keys()})).lower()
 if ('lacerda | torre externa - implantacao osm' in o.name.lower() or 'entrada superior lacerda' in o.name.lower() or 'elevador lacerda' in text or '59224731' in text):
  if o.type in {'MESH','CURVE','FONT','EMPTY'}: candidates.append(row(o))
# V4 references
refs=[row(tower),row(floor),row(hall)]
# distances between candidate bbox centers and tower/current upper shell endpoint
def centerxy(r):return Vector((r['center_xy'][0],r['center_xy'][1]))
metrics=[]
v4t=centerxy(refs[0]); v4front_s=max(refs[1]['s_range']); v4front=T+EX*v4front_s
for r in candidates:
 c=centerxy(r);metrics.append({'name':r['name'],'dist_to_v4_tower_xy':round((c-v4t).length,3),'dist_to_v4_upper_front_xy':round((c-v4front).length,3),'candidate_center_s':round(float((c-T).dot(EX)),3),'candidate_center_l':round(float((c-T).dot(EY)),3)})
print('ELEVADOR_OSM_ANCHOR_AUDIT_BEGIN')
print(json.dumps({'v4':refs,'candidates':candidates,'metrics':metrics},ensure_ascii=False,separators=(',',':'),default=str))
print('ELEVADOR_OSM_ANCHOR_AUDIT_END')
